// Everything the run needs, plus the three things a human has to fill in.
const N8N_URL = 'http://localhost:5678';
const GITHUB_OWNER = '';    // TODO: the repository owner, e.g. Dev-In-Crypt
const GITHUB_REPO = '';     // TODO: the repository name, e.g. n8n-personal
const BRANCH = 'backup';    // never main: this branch holds backups and nothing else
const ALERT_CHAT_ID = '';   // TODO: the Telegram chat that receives the summary
const TIMEZONE = 'Europe/Madrid';
const PAGE_LIMIT = 250;
const MAX_WORKFLOWS = 500;

if (!GITHUB_OWNER || !GITHUB_REPO) {
  throw new Error('GITHUB_OWNER and GITHUB_REPO are not configured in "Prepare"');
}
if (!ALERT_CHAT_ID) throw new Error('ALERT_CHAT_ID is not configured in "Prepare"');

const api = N8N_URL.replace(/\/+$/, '') + '/api/v1';
const gh = 'https://api.github.com/repos/' + GITHUB_OWNER + '/' + GITHUB_REPO;
const now = DateTime.now().setZone(TIMEZONE);

return [{
  json: {
    branch: BRANCH,
    chatId: ALERT_CHAT_ID,
    timezone: TIMEZONE,
    date: now.toFormat('yyyy-LL-dd'),
    pageLimit: PAGE_LIMIT,
    maxWorkflows: MAX_WORKFLOWS,
    repoLabel: GITHUB_OWNER + '/' + GITHUB_REPO,
    // excludePinnedData asks n8n not to send captured run data at all. The normaliser
    // strips it again anyway, because a backup that leaves the machine should not depend
    // on a query parameter being honoured.
    listUrl: api + '/workflows?limit=' + PAGE_LIMIT + '&excludePinnedData=true',
    workflowUrl: api + '/workflows/',
    refUrl: gh + '/git/ref/heads/' + BRANCH,
    refsUrl: gh + '/git/refs',
    updateRefUrl: gh + '/git/refs/heads/' + BRANCH,
    commitUrl: gh + '/git/commits/',
    createCommitUrl: gh + '/git/commits',
    treesUrl: gh + '/git/trees',
    branchUrl: 'https://github.com/' + GITHUB_OWNER + '/' + GITHUB_REPO + '/tree/' + BRANCH,
  },
}];

// One item per workflow to fetch.
//
// The guards below all protect the same thing: a backup that quietly covers less than the
// instance is worse than no backup, because it looks like it worked.
const state = $('Prepare').first().json;
const res = $input.first().json || {};
const body = res.body === undefined ? res : res.body;
const list = Array.isArray(body && body.data) ? body.data : Array.isArray(body) ? body : null;

if (!list) throw new Error('the workflow list did not come back as a list');
if (body && body.nextCursor) {
  throw new Error('the instance has more workflows than one page of ' + state.pageLimit
    + '; raise PAGE_LIMIT in "Prepare" rather than backing up a subset');
}
if (list.length > state.maxWorkflows) {
  throw new Error('the instance reports ' + list.length + ' workflows, above the cap of ' + state.maxWorkflows);
}
// An empty list means the key lost its permissions, or the instance was reset. Committing
// that would replace the whole backup branch with nothing, which is how a backup deletes
// the thing it was protecting.
if (!list.length) throw new Error('the instance reports no workflows at all; refusing to commit an empty backup');

return list.map((w) => ({
  json: { id: w.id, name: w.name, url: state.workflowUrl + w.id },
}));

// Turns each workflow into a file whose diff a human can actually read, and refuses to
// hand anything to GitHub that looks like a secret.
const state = $('Prepare').first().json;
const requests = $('Fan out workflows').all().map((i) => i.json);
const responses = $input.all();

// Dropped because they move on their own. updatedAt and versionId change on every save,
// triggerCount on every run, meta carries the instance id, and shared carries ownership
// rows. Keeping them would make every backup differ from the last, and a diff that is
// always noisy is a diff nobody reads.
//
// pinData and staticData are dropped for a different reason: pinData is real captured
// data and staticData holds cursors and tokens. Neither belongs in a file bound for a
// remote.
const VOLATILE = new Set([
  'updatedAt', 'createdAt', 'versionId', 'triggerCount', 'meta', 'shared', 'pinData', 'staticData',
]);

// The scan runs before anything is sent. A secret found while reviewing a diff has
// already been pushed.
const SECRETS = [
  { name: 'json web token', re: /eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{10,}/ },
  { name: 'openai-style key', re: /\bsk-[A-Za-z0-9]{20,}/ },
  { name: 'anthropic key', re: /\bsk-ant-[A-Za-z0-9_-]{16,}/ },
  { name: 'github token', re: /\bgh[pousr]_[A-Za-z0-9]{30,}/ },
  { name: 'aws access key id', re: /\bAKIA[0-9A-Z]{16}\b/ },
  { name: 'telegram bot token', re: /\b\d{8,}:[A-Za-z0-9_-]{30,}\b/ },
  { name: 'private key block', re: /-----BEGIN [A-Z ]*PRIVATE KEY-----/ },
  { name: 'bearer token', re: /[Bb]earer\s+[A-Za-z0-9._-]{20,}/ },
];

const sortDeep = (v) => {
  if (Array.isArray(v)) return v.map(sortDeep);
  if (v && typeof v === 'object') {
    const out = {};
    for (const k of Object.keys(v).sort()) out[k] = sortDeep(v[k]);
    return out;
  }
  return v;
};

const slug = (s) => String(s == null ? '' : s)
  .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'workflow';

const files = [];
const credentials = new Map();
const failed = [];

for (let i = 0; i < responses.length; i++) {
  const req = requests[i];
  if (!req) continue;
  const res = responses[i].json || {};
  const status = Number(res.statusCode == null ? 200 : res.statusCode);
  const wf = res.body === undefined ? res : res.body;

  if (status < 200 || status >= 300) { failed.push(req.name + ' (http ' + status + ')'); continue; }
  if (!wf || !Array.isArray(wf.nodes)) { failed.push(req.name + ' (the response carried no nodes)'); continue; }

  const clean = {};
  for (const k of Object.keys(wf)) if (!VOLATILE.has(k)) clean[k] = wf[k];

  clean.nodes = wf.nodes
    .map((n) => {
      const node = {};
      for (const k of Object.keys(n)) if (k !== 'credentials') node[k] = n[k];
      if (n.credentials && typeof n.credentials === 'object') {
        const refs = {};
        for (const type of Object.keys(n.credentials).sort()) {
          const c = n.credentials[type];
          // The name and nothing else. The id is local to this instance and would churn
          // the diff after any restore, and no other field of a credential reference has
          // any business in a file that leaves the machine.
          const name = typeof c === 'string' ? c : (c && c.name);
          refs[type] = { name: name || null };
          credentials.set(type + '::' + (name || ''), { type, name: name || '(unnamed)' });
        }
        node.credentials = refs;
      }
      return node;
    })
    // n8n returns nodes in storage order, which shifts as a workflow is edited. Sorting by
    // name means today's file differs from yesterday's only where something really changed.
    // Node names are unique in n8n and connections are keyed by name, so the order carries
    // no meaning to restore.
    .sort((a, b) => String(a.name).localeCompare(String(b.name)));

  // Two spaces and a trailing newline, so a renamed node is a one-line diff rather than a
  // rewritten file.
  const content = JSON.stringify(sortDeep(clean), null, 2) + '\n';
  files.push({ path: 'backup/workflows/' + wf.id + '-' + slug(wf.name) + '.json', content });
}

if (failed.length) {
  throw new Error('could not read ' + failed.length + ' workflow(s), so this backup would be '
    + 'incomplete: ' + failed.join(', '));
}

const credList = [...credentials.values()]
  .sort((a, b) => a.type.localeCompare(b.type) || a.name.localeCompare(b.name));

// Deliberately carries no date. A file that changes every day would produce a commit
// every day, which would destroy the one property this workflow is supposed to have.
const credMd = [
  '# Credentials in use',
  '',
  'Names and types only. The n8n API never returns credential values and none are stored',
  'here. This is the set referenced by the backed-up workflows rather than every credential',
  'on the instance: the public API has no endpoint that lists them.',
  '',
  '| Type | Name |',
  '| --- | --- |',
  ...(credList.length
    ? credList.map((c) => '| `' + c.type + '` | ' + c.name + ' |')
    : ['| _none_ | _no workflow references a credential_ |']),
  '',
].join('\n');
files.push({ path: 'backup/credentials.md', content: credMd });

for (const f of files) {
  for (const s of SECRETS) {
    if (s.re.test(f.content)) {
      throw new Error('refusing to back up: a ' + s.name + ' pattern appears in ' + f.path);
    }
  }
}

files.sort((a, b) => a.path.localeCompare(b.path));

return [{
  json: {
    ...state,
    files,
    workflowCount: files.length - 1,
    credentialCount: credList.length,
    // No base_tree: the tree is the entire content of the backup branch, so a workflow
    // deleted on the instance disappears from the backup instead of lingering for ever.
    treePayload: {
      tree: files.map((f) => ({ path: f.path, mode: '100644', type: 'blob', content: f.content })),
    },
  },
}];

// Decides whether there is anything to commit, and builds the commit if there is.
const state = $('Normalise').first().json;

const refRes = $('Get branch head').first().json || {};
const refStatus = Number(refRes.statusCode == null ? 0 : refRes.statusCode);
const branchExisted = refStatus === 200;
if (!branchExisted && refStatus !== 404) {
  throw new Error('GitHub answered ' + refStatus + ' when asked for the ' + state.branch + ' branch');
}
const parentSha = branchExisted && refRes.body && refRes.body.object ? refRes.body.object.sha : null;

let baseTreeSha = null;
if (branchExisted) {
  // The node did not run when the branch is new, and asking for it then throws.
  try {
    const c = $('Get base commit').first().json || {};
    const body = c.body === undefined ? c : c.body;
    baseTreeSha = (body && body.tree && body.tree.sha) || null;
  } catch (e) {
    baseTreeSha = null;
  }
}

const treeRes = $input.first().json || {};
const treeBody = treeRes.body === undefined ? treeRes : treeRes.body;
const newTreeSha = treeBody && treeBody.sha;
if (!newTreeSha) throw new Error('GitHub did not return a sha for the new tree');

// A tree sha is a hash of the content it holds. Identical content hashes identically, so
// this single comparison is the whole of "commit only when something changed" - there is
// no diff to compute and nothing to get subtly wrong.
const changed = newTreeSha !== baseTreeSha;

const { files, treePayload, ...rest } = state;

return [{
  json: {
    ...rest,
    branchExisted,
    parentSha,
    baseTreeSha,
    newTreeSha,
    changed,
    commitPayload: {
      message: 'backup: ' + state.date,
      tree: newTreeSha,
      parents: parentSha ? [parentSha] : [],
    },
  },
}];

// The summary that goes to Telegram. It is sent only when something changed; a failed run
// is reported by the error handler in workflow 01 instead.
const state = $('Plan commit').first().json;
const commit = $('Create commit').first().json || {};
const commitBody = commit.body === undefined ? commit : commit.body;
const commitSha = (commitBody && commitBody.sha) || null;

const lines = [
  'n8n backup committed.',
  'Repository: ' + state.repoLabel + ' (' + state.branch + ')',
  'Date: ' + state.date,
  'Workflows: ' + state.workflowCount,
  'Credentials referenced: ' + state.credentialCount,
  state.branchExisted ? null : 'The ' + state.branch + ' branch did not exist and was created.',
  commitSha ? 'Commit: ' + String(commitSha).slice(0, 7) : null,
  state.branchUrl,
].filter(Boolean);

return [{ json: { ...state, commitSha, message: lines.join('\n') } }];
